onSubmit:
{{
  storeValue("lokalizacjeData", [])
    .then(() =>
      Number(RadioRodzaj.selectedOptionValue) === 0
        ? getSzukajMiejscowosc.run()
        : Number(RadioRodzaj.selectedOptionValue) === 1
          ? getSzukajGmina.run()
          : Number(RadioRodzaj.selectedOptionValue) === 2
            ? getSzukajPowiat.run()
            : []
    )
    .then((data) => {
      storeValue("lokalizacjeData", data || []);
    })
}}

onTextChanged:
{{
(async () => {

  const typ = Number(RadioRodzaj.selectedOptionValue);
  const token = Date.now();

  // Zapamiętujemy ostatnią zmianę tekstu
  await storeValue("lokalizacjaSearchToken", token);

  await storeValue("lokalizacjeData", []);

  let data = [];

  if (typ === 0) {

    data = await Promise.all([
      getSzukajMiejscowosc.run(),
      getCzyKSRRmiasto.run()
    ]).then(([data]) => data);

  } else if (typ === 1) {

    data = await getSzukajGmina.run();

  } else if (typ === 2) {

    data = await getSzukajPowiat.run();

  }

  await storeValue(
    "lokalizacjeData",
    data || []
  );

  // Czekamy 800 ms
  await new Promise(resolve => setTimeout(resolve, 800));

  // Sprawdzamy, czy w międzyczasie użytkownik
  // nie wpisał kolejnego znaku
  if (
    appsmith.store.lokalizacjaSearchToken !== token
  ) {
    return;
  }

  // Log tylko dla ostatniego wyszukiwania
  let opis = "";

  if (typ === 0) {
    opis = "Wyszukano miejscowość.";
  } else if (typ === 1) {
    opis = "Wyszukano gminę.";
  } else if (typ === 2) {
    opis = "Wyszukano powiat.";
  }

  await Log.write(
    "LOKALIZACJA_SEARCH",
    opis,
    appsmith.store.session.user.id,
    appsmith.store.session.user.name,
    appsmith.store.session.token
  );

})();
}}
